# generated by tools/ail2py.py from csv_column_stats.ail; edit the .ail until onelang s16
from csv_integer_stream import *
# Preserve the str API while avoiding whole-document row materialization.
def csv_column_stats(data: str, column: int) -> IntegerColumnStats:
    if column < 0:
        raise ValueError
    content: bytes = data.encode('utf-8')
    if _utf8_complete_length(content) != len(content):
        raise ValueError
    state: CsvIntegerState = CsvIntegerState(0, 0, 0, column, 0, 1, 0, 0, 0)
    stats: IntegerColumnStats = IntegerColumnStats(0, 0, 0, 0)
    _csv_integer_feed(state, stats, content)
    if state.mode == 2:
        raise ValueError
    if state.mode != 0 or state.field != 0:
        _csv_integer_finish_row(state, stats)
    return stats
